SELECT COUNT(*)
FROM stock_custom_plate
WHERE category_code = #{categoryCode}
  AND plate_name = #{plateName}
  AND active = 1

  AND id != #{excludeId}

SELECT id, category_code, plate_name, active, created_at, updated_at
FROM stock_custom_plate
WHERE category_code = #{categoryCode}
  AND active = 1
ORDER BY id
LIMIT #{limit} OFFSET #{offset}

